             raise KeyError(task.id)
         self._tasks[task.id] = task

     def delete(self, task_id: int) -> bool:
         return self._tasks.pop(task_id, None) is not None

     def next_id(self) -> int:
         value = self._next_id
         self._next_id += 1
         return value


