class TestTags:
    def test_add_tags(self, svc):
        svc.create("task")
        task = svc.add_tags(1, ["python", "flask"])
        assert len(task.tags) == 2

    def test_add_tags_deduplicates(self, svc):
        svc.create("task", tags=["python"])
        task = svc.add_tags(1, ["Python"])
        assert len(task.tags) == 1

    def test_remove_tag(self, svc):
        svc.create("task", tags=["python", "flask"])
        task = svc.remove_tag(1, "python")
        assert len(task.tags) == 1
        assert task.tags[0].name == "flask"

    def test_remove_tag_not_present_raises(self, svc):
        svc.create("task", tags=["python"])
        with pytest.raises(ValueError, match="not attached"):
            svc.remove_tag(1, "flask")

    def test_add_tags_missing_task_raises(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.add_tags(99, ["a"])

    def test_remove_tag_missing_task_raises(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.remove_tag(99, "a")


